Build the triangle from the positive side lengths, then attach the sign the quadrant demands. The acute angle in a reference triangle is $\alpha$ in quadrant 1, $\pi-\alpha$ in quadrant 2 and $-\alpha$ in quadrant 4.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=1.4]
\usetikzlibrary{angles,quotes,calc}
\coordinate (C) at (0,0);
\coordinate (B) at (3,0);
\coordinate (A) at (0,2);
\draw (C) -- (B) node[midway, below] {adjacent};
\draw (B) -- (A) node[midway, above right] {hypotenuse};
\draw (A) -- (C) node[midway, left] {opposite};
\coordinate (c1) at ($(C)!0.25cm!(B)$);
\coordinate (c2) at ($(C)!0.25cm!(A)$);
\draw (c1) -- ($(c1)+(c2)-(C)$) -- (c2);
\pic[draw,angle radius=0.7cm] {angle=A--B--C};
\node[anchor=west] at (3.25,0.25) {reference angle};
\end{tikzpicture}
[/tikz]

